export default function collect({ body, previous }) {
  const s = previous ?? { page: 0, items: [] };
  if (!Array.isArray(body)) throw Error("Invalid daily papers response");
  const items = s.items.concat(
    body.map((x) => {
      const paper = x.paper ?? x;
      if (!paper.id) throw Error("Paper ID missing");
      return { id: String(paper.id) };
    }),
  );
  return { state: { page: s.page + 1, items }, more: body.length === 100 };
}

