export default function next({ items, previous }) {
  const index = previous?.index ?? 0,
    paper = items[index];
  if (!paper) return { state: { index }, more: false, id: "", url: "", filter: {} };
  const id = paper.id;
  if (!/^[a-zA-Z0-9.\/-]+$/.test(id)) throw Error("Invalid paper ID");
  const url = "https://huggingface.co/papers/" + id;
  return {
    state: { index: index + 1 },
    more: true,
    id,
    url,
    filter: { property: "URL", url: { equals: url } },
  };
}

