export default function prepare({ paper, analysis, url, sourceId, date }) {
  if (!paper?.title || !paper?.summary) throw Error("Paper title or abstract missing");
  const rich = (s) => ({ rich_text: [{ text: { content: String(s ?? "").slice(0, 2000) } }] });
  return {
    parent: { data_source_id: sourceId },
    properties: {
      title: { title: [{ text: { content: String(paper.title).slice(0, 2000) } }] },
      URL: { url },
      abstract: rich(paper.summary),
      "scrap-date": { date: { start: date } },
      Classification: rich(analysis.Classification.join(", ")),
      Technical_Details: rich(analysis.Technical_Details),
      Data_and_Results: rich(analysis.Data_and_Results),
      keywords: rich(analysis.Keywords.join(", ")),
      "Core Introduction": rich(analysis.Core_Introduction),
    },
  };
}

